- Астынан өзендер ағып жатқан бақшалар, олар онда мәңгі қалады, және бұл зор табыс. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ) 4:13; 9:89
- Оларға өздерінен бұрынғылардың, Нұх, Ғад және Самуд елдерінің хабары келмеді ме? (أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ) 9:70; 14:9
- Аллаһтың жолында менің көмекшілерім кімдер? Хауарилер (шәкірттер) айтты: "Біз Аллаһтың көмекшілеріміз, біз иман келтірдік." (مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا) 3:52; 61:14
- Раббың Өз жолынан адасқанды жақсы біледі, және Ол тура жолға түскендерді жақсы біледі. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 16:125; 68:7
- Бұл, Аллаһтың Өзі ғана ақиқат екендігінен, ал олардың Одан өзге шақырғандары жалған болғандықтан. (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- Кім Аллаһқа және Оның елшісіне бағынса, Аллаһ оны астынан өзендер ағып жатқан бақшаларға кіргізеді. (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- Күмәнсіз, Ол сендерге өлексе, қан, шошқа етін және Аллаһтан басқаға арнап сойылғанды ғана арам етті. (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- Аллаһтан басқа ешкімге табынбаңдар; мен сендерге ұлы күннің азабынан қорқамын. (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- Бұл, көрінбейтін хабарлардың бірі, оны саған уахи етеміз; олар шешім қабылдаған кезде сен олардың қасында болмадың. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- Сендерге Раббыларыңнан өздеріңнің араларыңнан бір адам арқылы ескерту келді деп таң қаласыңдар ма, ол сендерді ескерту үшін? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- Айт: "Күмәнсіз, маған Аллаһтан басқа сендердің шақыратындарыңа табынуға тыйым салынды." (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- Өз жұбайлары немесе оң қолдары иелік еткендерден басқа, өйткені олар сөгілмейді. (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- Аллаһ түнді күндізге, күндізді түнге кіргізетіндіктен. (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- От, және ол үй-ішіне айтты: "Күте тұрыңдар, мен бір от көрдім, мүмкін сендерге одан бір нәрсе әкелермін." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- Ол айтты: "Мен одан артықпын; Сен мені оттан жараттың, ал оны балшықтан жараттың." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- Оларға: "Аллаһ түсірген нәрсеге және елшіге келіңдер" делінгенде. (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- Сен оларға қайғырма, және олардың айла-шарғыларынан қысылма. (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- Егер Аллаһ саған бір зиян жеткізсе, Онан басқа ешкім оны кетіре алмайды, және егер. (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- Олардан бұрынғы ұрпақтар, олар өз үйлерінде жүріп өтті; күмәнсіз, бұнда белгілер бар. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- Біз олардың жүректеріне оны түсінбеулері үшін перделер қойдық, және құлақтарына салмақ, және егер. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- Оларға елшілері айқын дәлелдемелермен келді, бірақ Аллаһ оларға әділетсіздік етуші емес, бірақ олар өздеріне-өздері әділетсіздік етті. (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- Және жер бетінде, Аллаһтан басқа сендерге ешбір қамқоршы да, көмекші де жоқ. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- Содан кейін сендер көрінбейтін және көрінетіннің Білушісіне қайтарыласыңдар, сонда Ол сендерге істегендеріңді хабарлайды. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- Түнді онда тынығуларың үшін, ал күндізді көрулерің үшін; күмәнсіз, бұнда ойлайтын ел үшін белгілер бар. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- Раббыңнан саған түсірілген нәрсе олардың көбінің басын көтеруі мен қарсылығын арттырады. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- Ол айтты: "Уа, менің елім! Айтыңдаршы, егер мен Раббым тарапынан айқын дәлелдеме үстінде болсам және Ол маған берсе." (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- Және олар айтады: "Оған Раббысы тарапынан бір белгі неге түсірілмеді?" Айт: "Күмәнсіз." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- Аллаһ тарапынан қайтарылмайтын күн келмей тұрып. (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- Бұл Аллаһтың кеншілігі, Ол оны қалағанына береді, және Аллаһ ұлы кеншілік иесі. (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- Күмәнсіз, малдарда сендерге үлгі бар; Біз сендерге олардың қарнындағы нәрседен ішкіземіз. (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- Бұл олардың Раббысы тарапынан ақиқат, және Аллаһ олардың істегендерінен ғапыл емес. (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- Олардың алдынан да, артынан да, Аллаһтан басқа ешкімге табынбаңдар. (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- Күмәнсіз, сендер әйелдерді қойып, еркектерге құмарлықпен келесіңдер; әлде сендер шектен шығушы елсіңдер. (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- Олар онда мәңгі қалады, аспандар мен жер тұрғанша, Раббыңның қалауынан басқа. (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- Аспандардағы және жердегілер, Аллаһтың қалағанынан басқа. (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- Онда олар алтын білезіктермен және інжу-маржанмен безендіріледі, және олардың киімдері жібектен. (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
- Және аспаннан су түсіріп, онымен сендерге жемістерді азық етіп шығарды. (وَأنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ) 2:22; 14:32
- Естеріңде болсын, Біз сендерден уәде алғанда және үстеріңе Тур тауын көтергенде: "Біз сендерге бергенді мықты ұстаңдар." (وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ) 2:63; 2:93
- Содан ол олардан бет бұрды және айтты: "Уа, менің елім! Мен сендерге Раббымның жарлығын жеткіздім және сендерге ақыл айттым." (فَتَوَلَّى عَنْهُمْ وَقَالَ يَاقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّي وَنَصَحْتُ لَكُمْ) 7:79; 7:93
- Астыларынан өзендер ағып жатыр, онда олар алтын білезіктермен безендіріледі. (تَجْرِي مِن تَحْتِهِمُ الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ) 18:31; 22:23
- Егер олардың жер бетіндегі барлық нәрсе және онымен бірге тағы да сонша болса, өздерін құтқару үшін. (لَوْ أَنَّ لَهُم مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا) 5:36; 13:18
- Ешбір жәндік жоқ, бірақ Ол оларды белгіленген мерзімге дейін кешіктіреді, және олардың мерзімі келгенде. (مِن دَابَّةٍ وَلَكِن يُؤَخِّرُهُمْ إِلَى أَجَلٍ مُّسَمًّى فَإِذَا جَاءَ أَجَلُهُمْ) 16:61; 35:45
- Біз сендерді топырақтан, сосын тамшыдан, сосын ұйыған қаннан, сосын. (خَلَقْنَاكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ) 22:5; 40:67
- Аллаһ қиямет күні олардың араларында таласқан нәрселеріне үкім шығарады. (فَاللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 22:69
- Саған білім келді, Аллаһтан басқа саған ешбір қамқоршы да жоқ. (جَاءَكَ مِنَ الْعِلْمِ مَا لَكَ مِنَ اللَّهِ مِن وَلِيٍّ وَلَا) 2:120; 13:37
