- Оның сыйы Раббысының қасында, оларға ешбір қорқыныш жоқ және олар. (أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:112; 2:262; 2:274; 2:277
- Раббысының қасында, оларға ешбір қорқыныш жоқ және олар қайғырмайды. (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- Кім тура жолмен жүрсе, ол өзі үшін жүреді, ал кім адасса. (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- Өзі үшін жүреді, ал кім адасса, ол өз зиянына адасады. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- Оған Раббысы тарапынан бір белгі неге түсірілмеді? Айт: Расында. (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- Иман келтіріп, ізгі істер істегендерге үзілмейтін сыйлық бар. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- Тіріні өліден шығарасың, өліні тіріден шығарасың. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- Аллаһ түсірген нәрсемен үкім етпегендер, міне, солар. (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- Ол көктер мен жерді және олардың арасындағыны алты күнде жаратты. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- Расында Аллаһ адамдарға кеңшілік иесі, бірақ көпшілігі. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- Аллаһ оларға әділетсіздік жасамады, бірақ олар өздеріне әділетсіздік жасады. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- Ол сендердің күнәларыңды кешіріп, астарынан өзендер ағатын бақтарға кіргізеді. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- Ол сендерге өлексені, қанды, шошқа етін және Аллаһтан басқаның атына сойылғанды арам етті. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- Мен, егер Раббыма қарсы келсем, ұлы күннің азабынан қорқамын. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- Бірақ оларға білім келгеннен кейін, араларындағы көреалмастықтан. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- Олар намазды толық орындайды және Берген ризықтан жасырын және ашық түрде садақа береді. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- Аллаһтан өзге, бізге пайда да, зиян да келтіре алмайтын нәрсеге шақырамыз ба? (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- Олар саған түсірілгенге және сенен бұрын түсірілгенге иман келтіреді. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- Аллаһтың көктен су түсіргенін көрмейсің бе? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- Бір істі қалаған кезде, оған: Бол! – дейді, сонда ол болады. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- Мадянға олардың бауыры Шұғайыпты (жібердік). Ол айтты: Әй, елім! Аллаһқа құлшылық етіңдер. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- Бұл ғайып хабарларынан, оны саған уахи етеміз; сен бұны білмедің. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- Олардың белгіленген мерзімі келгенде, оны бір сәтке кешіктіре де, ілгерілете де алмайды. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- Шайтанның ізімен жүрмеңдер, ол сендерге анық дұшпан. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- Адамдардың кейбіреулері ешбір білімсіз Аллаһ жайында тартысады. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- Аллаһ оны қалағанына береді, Аллаһ өте кеңшілікті. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- Әрбір жан өзінің істегеніне толық есеп береді және оларға әділетсіздік жасалмайды. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- Аллаһ арам еткен жанды, орынсыз түрде өлтірмеңдер. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- Бір істі қалаған кезде, оған: Бол! – дейді. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- Тозақтың есіктерінен кіріңдер, онда мәңгі қаласыңдар; тәкаппарлардың орны қандай жаман! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- Кітаптан үлес берілгендерді көрмедің бе? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- Оларға бақтар бар, астынан өзендер ағып жатады, онда мәңгі қалады. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- Әй, елім! Өздеріңнің тұрған жерлеріңде іс істеңдер, мен де істеймін; жақында білесіңдер. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- Аллаһқа және Оның Елшісіне қарсы шыққан кісіге тозақ оты бар, ол онда мәңгі қалады. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- Олардың жүректеріне оны түсінбеуі үшін перде қойдық, ал құлақтарына салмақ салдық. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- Біз ескертуші жіберген әрбір кентте олардың байлары: Біз. – деді. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- Олар: Раббыңнан бізге сұра, ол бізге оның не екенін анықтап берсін. – деді. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- Олар: Аллаһ. – дейді. Айт: Барлық мақтау Аллаһқа тән! Бірақ олардың көпшілігі. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- Оның елінің жауабы: Оларды қуып шығарыңдар. – деу ғана болды. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- Астынан өзендер ағып жатады, олар онда мәңгі қалады; бұл зор табыс. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- Міне, солар Раббысының тура жолында, және солар құтылушылар. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- Кімге қорлық азабы келеді және кімге тұрақты азап түседі. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- Жер бетінде жүріп, өтірік деушілердің соңы қалай болғанын көріңдер. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- Олар өз қолдарының істегені үшін оны ешқашан тілемейді, Аллаһ әділетсіздерді толық біледі. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- Ол кімнің өз жолынан адасқанын жақсы біледі, және Ол жақсы біледі. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- Аллаһ менің Раббым және сендердің Раббыларың, сондықтан Оған құлшылық етіңдер; бұл тура жол. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- Ол адамдарға кеңшілік иесі, бірақ олардың көпшілігі шүкір етпейді. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- Көктер мен жерді және олардың арасындағыны ақиқатпен және белгілі бір мерзімге ғана жараттық. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- Оларды бос қой, олар уәде етілген күндеріне жолыққанша, бос сөзбен айналысып ойнасын. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- Иман келтіргендерге жолыққанда: Біз иман келтірдік. – дейді, ал өздері жеке қалғанда. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- Олар Тәурат пен Інжілді және Раббыларынан түсірілгенді толық орындайды. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- Ол олардың алдындағыны және артындағыны біледі, ал олар Оны біліммен қамти алмайды. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- Ол көктер мен жерді алты күнде жаратқан. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- Расында бұл аятта сендерге бір белгі бар, егер иман келтірген болсаңдар. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- Адамдарға тура жол келгенде, олардың иман келтіруіне не кедергі болды? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- Олар Аллаһқа серік қосып, Оның жолынан адастыру үшін. Айт: Рахаттанып ал. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- Олар өздерінен ескертуші келгеніне таң қалды, ал кәпірлер: Бұл. – деді. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- Расында Раббың кімнің өз жолынан адасқанын жақсы біледі. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- Малын адамдарға көрсету үшін жұмсайтын және Аллаһқа иман келтірмейтін кісі сияқты. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- Сендерге Берген ризықтан, ол келмей тұрып садақа беріңдер. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- Ол көктердегі және жердегінің бәрін сендерге бағындырды. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- Біз сендердің шақырған нәрселеріңе күмәнданамыз. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- Расында Раббың қалағанына ризықты кеңітеді және тарылтады. Расында Ол. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- Көктер мен жердің және олардың арасындағының Раббысы, егер анық сенген болсаңдар. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- Біз Аллаһқа, бізге түсірілгенге және Ибраһим, Ысмайыл, Ысхақ, Жақып және ұрпақтарына түсірілгенге иман келтірдік. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- Әділетсіздерге ащы дауыс келіп, олар өз үйлерінде етпеттеп қалды. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- Олардың өздеріне қатысты істегендері үшін сендерге күнә жоқ. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- Раббың кімнің өз жолынан адасқанын жақсы біледі, және Ол. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- Өз әмірімен рухты (уахиды) қалаған құлына түсіреді. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- Мәриям ұлы Исаға анық дәлелдер бердік және оны Киелі Рухпен қолдадық. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- Қиямет күні олардың арасында таласқан нәрселеріне үкім шығару үшін. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- Біз оны астыңғы-үстіңгі етіп жібердік және оларға күйдірілген балшықтан тас жаудырдық. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- Оларға ескертсең де, ескертпесең де бірдей, олар иман келтірмейді. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- Адамдардан басқа, егер шыншыл болсаңдар, өлімді тілеңдер. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- Аллаһ, сендерге Одан басқа тәңір жоқ. Сонда қорықпайсыңдар ма? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- Біз оларға уәде еткеннің кейбірін саған көрсетсек те, не сені өлтірсек те, олар Бізге қайтарылады. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- Олар: Біз өліп топырақ және сүйек болғанда, шынымен қайта тірілеміз бе? – деді. (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- Кеңшілік Аллаһтың қолында, Ол оны қалағанына береді, Аллаһ. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- Көрінген және көрінбейтіннің бәрін Білушіге қайтарыласыңдар, сонда Ол істегендеріңді хабарлайды. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- Әй, иман келтіргендер! Аллаһтың сендерге берген нығметін еске алыңдар, сол кезде. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- Сенен бұрын да Біз уахи түсірген ер кісілерді ғана Елші етіп жібердік. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- Ол оның күнәларын кешіріп, астынан өзендер ағатын бақтарға кіргізеді. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- Науқас немесе сапарда болған адам, басқа күндерде есебін толтырсын. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- Олар ой-жорамалға ғана ереді және олар тек болжам жасайды. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- Аллаһқа және ақырет күніне үміт еткендерге жақсы үлгі бар. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- Көктер мен жерді және олардың арасындағыны ақиқатпен ғана жараттық. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- Қолыңды қойнына сал, ол ешбір ақаусыз аппақ болып шығады. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- Ол мейірімімен қалағанын ерекшелейді, Аллаһ өте кеңшілікті. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- Аллаһтың көктер мен жердің патшалығы иесі екенін білмейсің бе? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- Өздерің үшін алдын ала жіберген жақсылықты Аллаһтың қасында табасыңдар. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- Қайдан шықсаң да, жүзіңді Масжид әл-Харамға қарат. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- Сенен бұрынғылар өтті, Аллаһтың жолында ешбір өзгеріс таппайсың. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- Көктердегі және жердегінің бәрі Оған тән. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- Ешбір әйел жүкті болмайды және босанбайды, тек Оның білімімен ғана. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- Ол түнді, күнді, ай мен күнді бағындырды; бәрі белгіленген мерзімге дейін жүреді. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- Астынан өзендер ағып жатады, олар онда мәңгі қалады, бұл сыйлық. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- Ол: Жоқ, сендердің өздеріңнің көңілдерің бір істі қызықтырды; сабыр қылу жақсы. – деді. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- Көктердегі және жердегі нәрселер, және Аллаһ. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- Оларға Елші келген сайын, олар оны мазақ етті. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- Олар: Әй, Мұса! Сен тастайсың ба, әлде біз тастайық па? – деді. (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- Ол сендерді өлтіреді, және сендердің кейбіреулерің ең кемеңгер жасына қайтарылады, сонда. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- Оларға Раббысының қасында бақтар бар, астынан өзендер ағып жатады, онда мәңгі қалады. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- Олардың жүректеріне оны түсінбеуі үшін перде қойдық, ал құлақтарына салмақ салдық. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- Аллаһтың уәдесі ақиқат, бірақ олардың көпшілігі білмейді. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- Бұл олардың Аллаһқа және Оның Елшісіне қарсы шыққандығынан; Аллаһқа қарсы шыққан кісіге. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- Ол күні Ол оларды шақырып: Менің серіктерім деп таңғандарың қайда? – дейді. (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- Аллаһтың көктер мен жерді жаратқанын көрмеді ме? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (Ол) сендерді топырақтан, сосын бір тамшы ұрықтан, сосын. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- Олар: Раббымыз, бізге Елші жібермедің бе, сонда аяттарыңа ерер едік? – дер еді. (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- Сосын олардың Раббысына қайтарылады, сонда Ол істегендерін хабарлайды. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- Олардың бұл жайында ешбір білімі жоқ, олар тек ой-жорамалға ереді. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- Біз ата-бабаларымызды бір дін үстінде таптық, біз олардың ізін қуушымыз. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- Кітап берілгендер, оларға білім келгеннен кейін ғана (таласты). (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- Ибраһим: Раббым, осы мекенді қауіпсіз ет! – дегенде. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- Ол сендерге есту, көру және жүректер берді; аз ғана шүкір етесіңдер. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- Аллаһтың аяттары жайында ешбір дәлелсіз тартысатындар. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- Ибраһимнің ханиф дініне еріңдер, ол Аллаһқа серік қосушылардан емес еді. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- Сендерді Перғауынның әулетінен құтқарғанымызда, олар сендерге қатты азап берді. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- Бұл дұрыс дін, бірақ адамдардың көпшілігі білмейді. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- Аллаһтың сендерге көктердегі және жердегі нәрселерді бағындырғанын көрмейсің бе? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- Кәпірлер: Бұл анық сиқыр ғана. – дер еді. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- Оларға анық аяттарымыз оқылғанда, кәпірлер: – дейді. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- Мәңгілік бақтар, астынан өзендер ағып жатады, олар онда мәңгі қалады. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- Ол қалағанын жаратады; Аллаһтың әрбір нәрсеге күші жетеді. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- Күнәларыңды кешіріп, белгілі бір мерзімге дейін кешіктіруі үшін. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- Бізді ата-бабаларымыз табынған нәрседен тыйғыңдар келе ме? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- Раббың періштелерге: Мен балшықтан адам жаратамын. – дегенде. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- Ол мейірімінің алдынан желдерді қуаныш хабаршысы етіп жібереді. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- Айт: Жер бетінде жүріп, соңы қалай болғанын көріңдер. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- Көктер мен жердің жаратылуында және түн мен күннің ауысуында (белгілер бар). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- Аллаһқа көркем қарыз беретін кім? Ол оны бірнеше есе арттырып береді. (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- Олардың арасында Аллаһ түсіргенмен үкім ет, олардың қалауларына ерме. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- Олар періштелердің келуін немесе Раббыңның әмірінің келуін күте ме? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- Расында Аллаһқа қарсы жалған айтқандар құтылмайды. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- Перғауын әулеті және олардан бұрынғылар сияқты, олар аяттарымызды өтірік деді. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- Ол иман келтіріп, ізгі істер істегендерге, оларға сыйлық болатынын қуанышпен хабарлайды. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- Аллаһ қалаған құлына ризықты кеңітеді және тарылтады. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- Көрінген және көрінбейтіннің бәрін Білушіге қайтарыласыңдар, сонда Ол істегендеріңді хабарлайды. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- Жақын туыстар Аллаһтың Кітабында бір-біріне жақынырақ. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — міндетті (орындау керек; тастаса күнә)
- mustahabb / mandub (مستحب / مندوب) — ұсынылатын (орындалса сауап, тасталса күнә емес)
- mubah (مباح) — бейтарап / рұқсат етілген (сауап та, күнә де жоқ)
- makruh (مكروه) — жағымсыз (ұнамайды, бірақ орындалса күнә емес)
- haram (حرام) — тыйым салынған (орындау күнә)
- halal (حلال, рұқсат етілген / заңды) — мубах пен мустахабты қамтиды — тыйым салынбағанның бәрі
- Тек Аллаһқа құлшылық етіңдер және Одан көмек/жәрдем сұраңдар. 1:5
- Тек Аллаһқа құлшылық етіңдер. 2:21
- Аллаһқа ешбір серік қоспаңдар. 2:22
- Аллаһ – кешіруші (тәубе қабылдаушы), Ол Адамның (ғ.с.) тәубесін қабыл алды. 2:37
- Ақиқатты жалғанмен араластырмаңдар және ақиқатты жасырмаңдар. 2:42
- Намазды (күнделікті намаздарды) орындаңдар және зекет (садақа) беріңдер. 2:43
- Өздерің амал еткеннен кейін ғана басқаларға игілікті бұйрық етіңдер. 2:44
- Барлық істеріңде Аллаһтан көмек сұраңдар. 2:45
- Бұзақылыққа араласпаңдар және оны таратпаңдар. 2:60
- Адамдарды құлшылық ету орындарына баруға кедергі жасамаңдар. 2:114
- Мешіттің киелілігін құрметтеңдер. Намаз оқитын орындарыңды таза әрі пәк ұстаңдар. 2:125
- Аллаһты еске алыңдар (намазбен, тасбихпен және т.б.) және Ол сендерді еске алады, және Оған шүкір етіңдер. 2:152
- Қиыншылықтарда сабыр етіңдер. 2:153
- Шайтанның ізімен жүрмеңдер, ол анық дұшпан. 2:168
- Ешкімге соқыр ілеспеңдер. 2:170
- Барлық аманаттарды сақтаңдар және орындаңдар. Діни міндеттеріңді шынайы орындаңдар. Анттарыңды және уәделеріңді орындаңдар. Уәделерді, әсіресе Аллаһқа берген уәделерді сақтаңдар. Мұқтаждарға қолдау көрсетіңдер және қиындықтарды жеңілдетіңдер. Илаһи рақымнан айырылуға әкелетін күнәларды жасаудан аулақ болыңдар. Тәкаппарлық сендерді әділетсіздікке апармасын. 2:177
- Қисаста (жазадағы теңдік заңы) сендер үшін өмір бар. 2:179
- Рамазан айында ораза ұстаңдар. Тақуалар (Муттақин) болу үшін белгіленген оразаны ұстаңдар. 2:183
- Құранды түпкілікті жолбасшы ретінде құрметтеңдер. 2:185
- Бір-біріңнің малдарын әділетсіз жемеңдер және судьяларға (істеріңді ұсынбас бұрын) пара бермеңдер. 2:188
- Басқаларды сөзбен немесе іспен қыспаққа алмаңдар. Ешқашан басқыншы ретінде соғыспаңдар, тек қорғаныс үшін ғана. 2:190
- Жетімдерді қорғаңдар. Жетімдерге келсек, олардың мал-мүлкіне адалдықпен қараңдар және олардың мал-мүлкін жемеңдер. 2:220
- Тәубе етіңдер және Аллаһтан кешірім сұраңдар. Етеккір кезінде жыныстық қатынас жасамаңдар. Тазалықты (дене және рухани) сақтаңдар. 2:222
- Отбасыларыңа деген міндеттеріңді орындаңдар. 2:233
- Көшбасшыларды еңбегіне қарай таңдаңдар. 2:247
- Дінде зорлық жоқ. 2:256
- Мал-дүниені садақаға жұмсаңдар. Малда да, уақытта да жомарт болыңдар. 2:261
- Өз жомарттықтарыңды мақтанышпен бұзбаңдар. 2:264
- Шайтан сендерді кедейлікпен қорқытады және пасықтыққа (жаман істерге, заңсыз жыныстық қатынасқа, күнәларға) бұйырады. 2:268
- Мұқтаждарды іздеңдер және оларға көмектесіңдер. 2:273
- Өсімшілікпен және пайызбен айналыспаңдар. Пайыздық малды жемеңдер. Рибаны (өсімді) жемеңдер. 2:275
- Борышкер қиын жағдайда болса, төлеуге көбірек уақыт беріңдер. 2:280
- Сауда мәмілелерінде сөзіңде тұрыңдар. Қаржы істеріңде шыншыл болыңдар. Барлық міндеттемелеріңде адал болыңдар. Белгіленген мерзімге қарыз келісімін жасағанда, оны жазып қойыңдар. Коммерциялық келісім жасасқан сайын куәгерлер алыңдар. 2:282
- Барлық аманаттарды сақтаңдар және орындаңдар. 2:283
- Түсірілген Кітаптарға және барлық Пайғамбарларға иман келтіріңдер. 2:285
- Аллаһ ешкімге оның күші жетпейтін нәрсені жүктемейді. Адам өзінің жақсы істерінің сауабын алады және жаман істерінің жазасын тартады. Аллаһ ешкімге оның күші жетпейтін нәрсені жүктемейді; біз де олай жасамауымыз керек. Қиыншылықта да Аллаһтың жоспарына сеніңдер. 2:286
- Кім уәделерін орындаса және Аллаһтан қорқса, онда Аллаһ тақуаларды сүйеді. 3:76
- Егер шамаларың келсе, қажылықты орындаңдар. 3:97
- Бөлінбеңдер. 3:103
- Игілікке бұйрық етіңдер және жамандықтан тыю салыңдар. Қауымыңда әділдікті насихаттаңдар. Басқаларды Аллаһты еске алуға шақырыңдар. 3:104
- Мүміндер Аллаһқа тәуекел етулері керек. 3:122
- Рибаны (өсімді) жемеңдер. 3:130
- Рақымға ие болу үшін Аллаһқа және Оның Елшісіне бой ұсыныңдар. 3:132
- Аллаһ (Аллаһ жолында — садақа, қайырымдылық т.б.) байлықта да, кедейлікте де жұмсайтындарды, ашуды жұтатындарды және адамдарды кешіретіндерді сүйеді. 3:134
- Ашуды жұтыңдар. Ашуларыңды бақылаңдар. 3:134
- Басқалардың қателіктерін кешіріңдер және ғапу етіңдер. 3:135
- Сөзде дөрекі болмаңдар. Сенен өзгешелерге сабырлы болыңдар. 3:159
- Егер Аллаһ сендерге көмектессе, ешкім сендерді жеңе алмайды; ал егер Ол сендерді тастап кетсе, Одан кейін кім сендерге көмектесе алады? 3:160
- Әрбір жан өлімді татады. Тек Қиямет күні ғана толық сыйларыңды аласыңдар. 3:185
- Табиғаттың кереметтері мен ғаламның жаратылуы туралы терең ойланыңдар. Аллаһ ғаламды мағына мен мақсатпен жаратқанын біліңдер. 3:191
- Ерлер мен әйелдер іс-әрекеттері үшін тең сый-сияпат алады. 3:195
- Раббыларынан қорқатындар үшін (Жәннатта) астынан өзендер ағып жататын бақтар бар; олар онда мәңгі қалады, Аллаһтың сый-қонақжайлылығы ретінде. 3:198
- Әрбір істе әрқашан Аллаһтың разылығын іздеңдер. 3:200
- Раббыларыңнан қорқыңдар, Одан қорыққан болыңдар және (туыстық) байланыстарды үзбеңдер. 4:1
- Жетімдерге мал-мүлкін беріңдер және (өздеріңнің жамандарыңды) олардың (жақсыларына) айырбастамаңдар; және олардың мал-мүлкін (өз малдарыңа қосып) жемеңдер. 4:2
- Үйленетін әйелдеріңе маһрлерін (неке кезінде күйеуінің әйеліне беретін міндетті қалыңмалын) көңілмен беріңдер. 4:4
- Жетімдердің құқықтарын қорғаңдар. 4:6
- Мәйіттің малы отбасы мүшелеріне бөлінуі керек. Әйелдердің мұрагерлік құқығы бар. 4:7
- Жетімдердің малын әділетсіз жемеңдер. 4:10
- Мұрагерлікке қатысты бұйрықтарды орындаңдар. 4:11
- Әйелдерді олардың еркіне қарсы мұрагерлікке алуға тыйым салынады, және оларға қаталдық жасамаңдар. Олармен (әйелдермен) көрікті түрде тұрыңдар. Әйелдердің құқықтарын құрметтеңдер және сақтаңдар. Жұбайыңызға мейірімділік пен жанашырлықпен қараңыз. Әйелдерге құрметпен және әділдікпен қараңыз. 4:19
- Өздеріңе қандас туысқандарға үйленбеңдер. 4:23
- Бір-біріңді өлтірмеңдер. Аллаһ сендерге рақымды. Бір-біріңнің малдарын әділетсіз жемеңдер. 4:29
- Егер тыйым салынған үлкен күнәлардан аулақ болсаңдар, Аллаһ сендердің (кіші) күнәларыңды кешіріп, сендерді ардақты орынға (Жәннатқа) кіргізеді. 4:31
- Аллаһ сендердің кейбіреулеріңді басқаларыңнан артық еткен нәрселерді қызықпаңдар. Көреалмаушылық пен қызғаныштан аулақ болыңдар. 4:32
- Еркектер әйелдердің қамқоршылары мен басшылары, өйткені Аллаһ олардың бірін бірінен артық еткен және олар (әйелдерге) малдарынан жұмсайды. Еркек — отбасының қорғаушысы мен тірегі. 4:34
- Аллаһқа құлшылық етіңдер және Оған ешкімді серік қоспаңдар, ата-анаға, туыстарға, жетімдерге, кедейлерге, көршіге, жандарыңдағы жолдасқа, жолаушыға (кездескенге) және қолдарың иелік ететіндерге (құлдарға) жақсылық жасаңдар. Аллаһ тәкаппар және мақтаншақтарды ұнатпайды. Басқаларға жақсылық жасаңдар. Әлсіздерге мейірімді болыңдар. Отбасылық байланыстарды сақтаңдар және туыстарды құрметтеңдер. 4:36
- Саран болмаңдар. 4:37
- Аллаһ өзіне серік қосуды кешірмейді, бірақ одан басқасын қалағанына кешіреді. 4:48
- Басқаларға қызғанбаңдар. 4:54
- Аллаһ сендерге аманаттарды иелеріне қайтаруды бұйырады. Адамдар арасында үкім шығарғанда, әділдікпен үкім шығарыңдар. 4:58
- Аллаһқа және Оның Елшісіне бой ұсыныңдар. Араларыңдағы билік иелеріне тиісті құрмет көрсетіңдер. 4:59
- Әлсіздер мен осалдарды қыспаққа алмаңдар. 4:75
- Сендерге келген жақсылық Аллаһтан; ал сендерге келген жамандық өздеріңнен. 4:79
- Кім Елшіге (Мұхаммедке ﷺ) бой ұсынса, Аллаһқа бой ұсынды. 4:80
- Кім жақсы іс үшін шапағат етсе, оның сыйынан үлес алады; ал кім жаман іс үшін шапағат етсе, оның күнәсінен үлес алады. 4:85
- Мүміннің мүмінді өлтіруі дұрыс емес, тек қателескенде ғана. 4:92
- Кім бір мүмінді әдейі өлтірсе, оның жазасы — тозақ, онда мәңгі қалады. Аллаһтың қаһары мен қарғысы оның үстінде және оған үлкен азап дайындалған. 4:93
- Кім Аллаһ жолында (үйінен) көшіп кетсе, жер бетінде көп баспана мен кеңшілік табады. 4:100
- Намаздарыңды уақытында орындаңдар. 4:103
- Аманаттарына опасыздық жасайтындарды қолдамаңдар және олардың адвокаты болмаңдар. 4:105
- Аллаһтан кешірім сұраңдар, Аллаһ кешіруші, мейірімді. 4:106
- Ей, иман келтіргендер! Әділдікте мықты болыңдар, Аллаһ үшін куәгер болыңдар, егер өздеріңе, ата-аналарыңа немесе туыстарыңа қарсы болса да, бай не кедей болса да. Әділдікті кешіктірмеңдер; қателерді түзету үшін дереу әрекет етіңдер. 4:135
- Екіжүзділер Аллаһты алдамақшы болады, бірақ Ол оларды алдайды. 4:142
- Екіжүзділер Оттың ең төменгі қабатында болады; және олар үшін ешбір көмекші таба алмайсың. 4:145
- Аллаһ жаман сөздің ашық айтылуын ұнатпайды, тек зұлымдыққа ұшыраған адамнан басқа. 4:148
- Елшілерді қуаныш хабаршылары және ескертушілер ретінде жібердік, Елшілер (келген) соң адамдардың Аллаһқа қарсы дәлелі болмауы үшін. 4:165
- Уәделерің мен анттарыңды орындаңдар. 5:1
- Игілік пен тақуалықта бір-біріңе көмектесіңдер, күнә мен дұшпандықта көмектеспеңдер. 5:2
- Өлексені, қанды және шошқа етін жемеңдер. 5:3
- Әділ болыңдар, басқаларға деген дұшпандық пен өшпенділік сендерді әділдіктен ауытқытпасын. Әділ болыңдар. Әділдік тақуалыққа жақын екенін біліңдер. Әділдікті кешіктірмеңдер; қателерді түзету үшін дереу әрекет етіңдер. 5:8
- Аллаһқа жақындау жолдарын іздеңдер және Оның жолында қолдарыңнан келгенше күресіңдер. Табысты болуларың үшін. 5:35
- Анттарың мен уәделеріңді орындаңдар. 5:89
- Мас қылатын ішімдіктерден және алкогольден аулақ болыңдар. Мас қылатын ішімдіктерден (барлық алкогольдік сусындар), құмар ойындардан, пұттардан және (бакты немесе шешім іздеуге арналған) жебелерден қатаң түрде аулақ болыңдар, бұлардың барлығы шайтанның ісінің жамандықтары. 5:90
- Қажылық немесе ұмра (зиярат) үшін ихрам күйінде болғандарыңда аң ауламаңдар. 5:95
- Егер сендерге айқындалса, қиындық тудыруы мүмкін нәрселер туралы сұрамаңдар. 5:101
- Басқалардың құдайларын балағаттамаңдар. Олардың (кәпірлердің) Аллаһтан өзге табынатын нәрселерін балағаттамаңдар, әйтпесе олар да білместікпен Аллаһты балағаттар. 6:108
- Жер бетіндегі көпшілікке ерсеңдер, олар сендерді Аллаһтың жолынан адастырады. Олар тек болжамға ереді және олар тек өтірік айтады. 6:116
- (Адамдар) барлық күнәларды, ашық және жасырын, тастаңдар. 6:120
- (Мүміндер) үстіне Аллаһтың есімі (малды сойғанда) аталмаған (еттен) жемеңдер. 6:121
- Аллаһ кімді тура жолға салғысы келсе, оның кеудесін Ислам үшін кеңейтеді; ал кімді адастырғысы келсе, оның кеудесін тар және қысылған етеді. 6:125
- Шығындарыңда орташа болыңдар және ысырапшылдықтан аулақ болыңдар. Барлық жаратылыстардың құқықтарын қорғаңдар. 6:141
- Аллаһқа ешнәрсені серік қоспаңдар, ата-анаға жақсылық жасаңдар, кедейліктен қорыққаннан балаларыңды өлтірмеңдер, пасықтыққа жақындамаңдар, Аллаһ тыйым салған жанды өлтірмеңдер, тек әділ себеппен ғана. 6:151
- Шыншыл болыңдар; ешбір мәмілелеріңде алдамаңдар. Жетімнің малына жақындамаңдар, тек оны жақсарту үшін ғана, өлшеуді және таразыны әділдікпен толық орындаңдар, сөйлегенде, тіпті жақын туысқа қатысты болса да, шындықты айтыңдар және Аллаһтың уәдесін орындаңдар. 6:152
- Тура жолмен жүріңдер және (басқа) жолдармен жүрмеңдер, себебі олар сендерді Оның жолынан айырады. 6:153
- (Мұхаммед ﷺ) айт: "Расында, менің намазым, менің құлшылығым, менің өмірім және менің өлімім — әлемдердің Раббысы Аллаһ үшін." 6:162
- Тәкаппар болмаңдар. 7:13
- Шайтан сендерді алдамасын. 7:27
- (Мұхаммед ﷺ) айт: "Раббым әділдікке бұйырды…" 7:29
- Барлық істерде Аллаһ белгілеген шекараларды сақтаңдар. Сөз бен істе шектен шықпаңдар. Жеңдер және ішіңдер, бірақ шектен шықпаңдар. Намаз уақытында әдемі киімдер киіңдер. 7:31
- Аллаһ аспандар мен жерді алты күнде жаратты, сосын Аршқа (Өз ұлықтығына лайықты түрде) орнықты. 7:54
- Раббыларыңа кішіпейілділікпен және жасырын түрде жалбарыныңдар. Ол шектен шығушыларды ұнатпайды. 7:55
- Жер беті түзелгеннен кейін онда бұзақылық жасамаңдар және Одан қорқып, үміт етіп жалбарыныңдар. 7:56
- Ал жамандық істеп, сосын одан кейін тәубе етіп, иман келтіргендер, Раббың сол (барлығынан) кейін кешіруші, мейірімді. 7:153
- (Мұхаммед ﷺ) айт: "Ей, адамдар! Расында мен Аллаһтың Елшісімін, сендердің бәріңе…" 7:158
- Барлық көркем есімдер Аллаһтікі, сондықтан Оны солармен шақырыңдар және Оның есімдері туралы ауытқығандарды тастаңдар… 7:180
- Аллаһ кімді адастырса, оған ешбір жолбасшы жоқ; және Ол оларды адасуларында соқыр күйінде тастап қояды. 7:186
- Кешірімділік таныт, игілікке бұйыр, надандардан бет бұр (яғни оларды жазалама). 7:199
- Басқалардың қателерін кешіріңдер. 7:199
- Егер шайтаннан бір азғыру келсе, Аллаһтан пана тіле. Ол естуші, білуші. 7:200
- Мүміндер — Аллаһ еске алынғанда, жүректері қорқынышқа толып, Оның аяттары оқылғанда, имандары артатындар… 8:2
- Аллаһқа және Оның Елшісіне опасыздық жасамаңдар және аманаттарыңа (Аллаһ сендерге жүктеген барлық міндеттерге) біле тұра опасыздық жасамаңдар. 8:27
- Егер Аллаһтан қорықсаңдар және Оған бой ұсынсаңдар, Ол сендерге Фурқан (ақиқат пен жалғанды ажырату өлшемі, немесе әрбір қиындықтан шығу жолы) береді. 8:29
- Кәпірлер мал-дүниелерін (адамдарды) Аллаһтың жолынан тосуға жұмсайды, және олар оны жұмсай береді; бірақ соңында ол оларға өкінішке айналады. 8:36
- Кәпірлерге айт: егер олар (күпірліктен) тыйылса, өткендері кешіріледі. Ал егер олар (соған) қайтса, онда бұрынғылардың (жазаланғандардың) мысалдары өтіп кетті (ескерту ретінде). 8:38
- (Дұшпан) күшіне кездескенде, мықты болыңдар және Аллаһтың есімін көп еске алыңдар (тілмен де, жүрекпен де), табысты болуларың үшін. 8:45
- Әрі тәкаппарланып, әрі адамдарға көріну үшін үйлерінен шыққандар және (адамдарды) Аллаһтың жолынан тосқандар сияқты болмаңдар. 8:47
- Аллаһ бір елге берген нығметін, олар өздеріндегіні өзгертпейінше, өзгертпейді. 8:53
- Аллаһтың қасында ең жаман жан-жануарлар — кәпірлер. 8:55
- Аллаһ өзіне иман келтіргендердің жүректерінің арасына сүйіспеншілік пен достық салады. 8:63
- Қорғау сұрағандарды қорғаңдар және оларға көмектесіңдер. 9:6
- Мүшріктердің Аллаһтың мешіттерін күтіп-ұстауларына болмайды. 9:17
- Олар (кәпірлер, яһудилер және христиандар) Аллаһтың нұрын (Мұхаммед ﷺ жіберілген — исламдық бірқұдайшылық) ауыздарымен өшіргісі келеді, бірақ Аллаһ кәпірлер жанына саймаса да, Өз нұрын толықтырудан басқаға жол бермейді. 9:32
- Садақалар (зекет) тек мыналарға арналған: 1) кедейлер, 2) мұқтаждар, 3) оны жинаумен айналысатындар, 4) жүректері Исламға бейімделетіндер, 5) тұтқындарды босату, 6) борышкерлер, 7) Аллаһ жолында (мүжахидтерге), және 8) жолаушыларға. 9:60
- Кім Аллаһқа және Оның Елшісіне (ﷺ) қарсы тұрса және дұшпандық танытса, оған тозақ оты бар, онда мәңгі қалады. Бұл үлкен масқара. 9:63
- Екіжүзділер, ерлер мен әйелдер, бір-бірінен. Олар Аллаһты ұмытты, сондықтан Ол да оларды ұмытты. 9:67
- Тазалыққа ұмтылыңдар. Мешіттің киелілігін құрметтеңдер. 9:108
- (Пайғамбар мен мүміндерге) мүшріктер үшін, тіпті туыс болса да, олардың тозақтық екені анықталғаннан кейін (күпірлік күйінде өлгендіктен) кешірім сұрауларына болмайды. 9:113
- Аллаһқа жала жапқаннан немесе Оның аяттарын жалғанға шығарғаннан кім үлкен зұлым? Күнәкарлар ешқашан табысқа жетпейді! 10:17
- Олар Аллаһтан өзге өздеріне зиян да, пайда да келтіре алмайтын нәрселерге табынады және: "Бұлар Аллаһтың қасында біздің шапағатшыларымыз" дейді. Айт: "Аллаһқа аспандар мен жердегі Ол білмейтін нәрсені айтып жатырсыңдар ма?" Ол олардың серік қосқан нәрселерінен пәк және жоғары! 10:18
- Жамандықтың жазасы — өзі сияқты жамандық. 10:27
- Міне, Аллаһ — сендердің шынайы Раббыларың. Ақиқаттан кейін адасудан басқа не бар? Қалайша теріс айналдырылып жатырсыңдар? 10:32
- Олардың көпшілігі болжамға ереді. Болжам ақиқатқа еш пайдасыз. 10:36
- Расында! Аллаһ адамдарға ешбір әділетсіздік жасамайды; бірақ адамдар өздеріне әділетсіздік жасайды. 10:44
- Аллаһтың мейірімі адамның жинап немесе қорлай алатын нәрселерінен жақсы екенін біліңдер. 10:58
- Аллаһтың аяттарын жалғанға шығарушылардан болмаңдар, әйтпесе зиян шегушілерден боласыңдар. 10:95
- Егер Аллаһ саған бір зиян жеткізсе, оны Одан басқа ешкім ала алмайды; ал егер Ол саған бір жақсылық қаласа, Оның мейірімін ешкім кері қайтара алмайды, Ол оны құлдарынан қалағанына жеткізеді. 10:107
- Жер бетінде ешбір аң жоқ, оның ризығы Аллаһқа тәуелді болмасын. Және Ол оның орнын және сақталатын жерін (жатырда, қабірде және т.б.) біледі. 11:6
- Егер адамға Өзімізден бір рақым таттырсақ, содан кейін оны тартып алсақ, ол үмітсіз, шүкіршіліксіз болады. 11:9
- Кім дүние тіршілігін және оның көркін қаласа, оларға ондағы амалдарының ақысын толық береміз және оған кемітілмейді. 11:15
- Біз оларға әділетсіздік жасамадық, бірақ олар өздеріне әділетсіздік жасады. Аллаһтан өзге шақырған құдайлары, Раббыңның бұйрығы келгенде, оларға еш пайда бермеді және олардың құрбанынан басқа ештеңе бермеді. 11:101
- Ол (азап) келетін күні, Оның (Аллаһтың) рұқсатынсыз ешкім сөйлемейді. Олардың кейбіреулері — бақытсыз, (кейбіреулері) — бақытты болады. 11:105
- Бақытсыздар — отта, оларда ыңылдау мен өксіру бар. 11:106
- Олар онда мәңгі қалады, аспандар мен жер тұрғанша, бірақ Раббың қаласа ғана басқаша. Раббың қалағанын істеуші. 11:107
- Ал бақыттылар — жәннатта, онда мәңгі қалады, аспандар мен жер тұрғанша, бірақ Раббың қаласа ғана басқаша, үзілмейтін сый ретінде. 11:108
- Зұлымдарға бейім болмаңдар, әйтпесе от сендерге тиеді, және Аллаһтан өзге қорғаушыларың болмайды, сосын сендерге көмек көрсетілмейді. 11:113
- Намазды күннің екі басында және түннің бір бөлігінде орындаңдар (яғни 5 уақыт намаз). Жақсылықтар жамандықтарды (яғни кіші күнәларды) кетіреді. 11:114
- Аспандар мен жердің құпиясы Аллаһтікі, және барлық істер Оған қайтарылады (шешім үшін). 11:123
- Бұйрық (немесе үкім) тек Аллаһтікі. Ол сендерге Одан басқа ешкімге құлшылық етпеуге бұйырды (бірқұдайшылық), бұл — тура дін, бірақ адамдардың көпшілігі білмейді. 12:40
- Аллаһтың рахымынан ешқашан үміт үзбеңдер. 12:87
- Адамдардың көпшілігі, тіпті сен қатты қаласаң да, иман келтірмейді. 12:103
- Олардың көпшілігі Аллаһқа серік қоспай иман келтірмейді (яғни олар мүшріктер). 12:106
- Ол (Құран) өтірік сөз емес, керісінше, оның алдындағы Кітаптардың (Тәурат, Інжіл және басқа Кітаптардың) растауы және әрбір нәрсенің егжей-тегжейлі түсіндірмесі, және иман келтірген адамдар үшін жолбасшы әрі рахым. 12:111
- Аллаһ қалағанына ризықты кеңейтеді және (қалағанына) тарылтады. 13:26
- Аллаһты зікір арқылы көп еске алыңдар. Аллаһқа иман келтіргендер, Оны еске алумен жүректері жай табады. 13:28
- Иман келтіріп, ізгі істер істегендерге қуаныш пен жан тыныштығы беріледі. 13:29
- Ақыреттен гөрі дүние тіршілігін артық санайтындар және (адамдарды) Аллаһтың жолынан (Исламнан) тосатындар және оны қисайтуды көздейтіндер — олар ұзақ адасуда. 14:3
- Құлшылықта кішіпейілділік пен шүкіршілікті ұстаныңдар. 14:7
- Раббысына күпірлік еткендердің мысалы — олардың амалдары күл сияқты, оны дауылды күнде жел күшті ұшырады; олар тапқан нәрселерінен ешнәрсе ала алмайды. 14:18
- Аллаһ иман келтіргендерді дүние тіршілігінде (яғни олар Аллаһқа ғана құлшылық етуді жалғастырады) және ақыретте мықты сөзбен бекітеді. 14:27
- Аллаһтың зұлымдардың (мүшріктердің, әділетсіздердің және т.б.) істегендерінен хабарсыз екенін ойламаңдар, бірақ Ол оларды көздері үрейден ашылатын Күнге дейін кешіктіреді. 14:42
- Аллаһ әрбір жанға тапқанына қарай сый беруі үшін. Аллаһ есеп алуда жылдам. 14:51
- Расында, адамды балшықтан, қара лайдан жараттық. 15:26
- Жындарды одан бұрын түтінсіз от жалынынан жараттық. 15:27
- Оның (тозақтың) жеті қақпасы бар; әрбір қақпа үшін (ерекше) күнәкарлар тобы бар. 15:44
- Ол адамды бір тамшы ұрықтан (еркек пен әйелдің жыныстық сұйықтығының қоспасынан) жаратты, сонда ол (адам) анық қарсылас болады. 16:4
- Мал-жануарларды, Ол сендер үшін жаратты; оларда сендерге жылылық (жылы киімдер) және көптеген пайдалар бар, және олардан жейсіңдер. 16:5
- Және (Ол жаратты) жылқыларды, қашырларды және есектерді, мінулерің үшін және әшекей ретінде. Және Ол сендер білмейтін нәрселерді жаратады. 16:8
- Ол аспаннан су (жаңбыр) түсіреді; одан ішесіңдер және одан малдарыңды жаятын өсімдіктер өседі. 16:10
- Ол теңізді сендерге бағындырды, одан жаңа ет (балық) жеулерің үшін және одан киетін әшекейлер шығаруларың үшін. 16:14
- Ол жер бетіне сендермен бірге сілкінбеуі үшін тұрған тауларды және өзендер мен жолдарды (жаратты), тура жол табуларың үшін. 16:15
- Жаратушы, жаратпайтын сияқты ма? Еске алмайсыңдар ма? 16:17
- Егер Аллаһтың нығметтерін санағыларың келсе, оларды санай алмайсыңдар. 16:18
- Аллаһ сендердің жасырғандарыңды және ашқандарыңды біледі. 16:19
- Олардың (мүшріктердің) Аллаһтан өзге шақырғандары ешнәрсе жарата алмайды, өздері жаратылған. 16:20
- (Олар) өлі, тірі емес, және қашан қайта тірілетіндерін білмейді. 16:21
- Бір нәрсені қалағанымызда, Оған деген сөзіміз: "Бол!" деу ғана, сонда ол болады. 16:40
- Жаман айла жасаушылар, Аллаһ оларды жерге жұтқызбай ма, немесе оларға азап күтпеген жерден келмей ме деп өздерін қауіпсіз санай ма? 16:45
- Сендердегі барлық нығметтер мен жақсылықтар Аллаһтан. Содан кейін сендерге қиындық келсе, Оған жалбарынасыңдар. 16:53
- Сосын Ол сендерден қиындықты алып тастаса, дереу сендердің бір бөлігіңдер Раббыларына (Аллаһқа) серік қосады. 16:54
- Мал-жануарларда сендерге үлгі бар. Біз сендерге олардың іштеріндегі нәрседен, қызыл мен қанның арасынан, таза сүт ішкіземіз, ол ішушілерге тәтті. 16:66
- Аллаһқа ұқсастық жасамаңдар (өйткені Оған ұқсас ешнәрсе жоқ, әрі Ол ешнәрсеге ұқсамайды). Аллаһ біледі, ал сендер білмейсіңдер. 16:74
- Аллаһ адамдарға есту, көру, ақыл және сезім бергенін біліңдер, шүкіршілік етулері үшін. 16:78
- Ашкөздік пен сарандықтан аулақ болыңдар. 16:97
- Құран оқығың келгенде, қуылған шайтаннан Аллаһқа пана тіле. 16:98
- Надандықпен істелген қате, егер адам тәубе етіп, өзін түзетсе, кешірілетінін біліңдер. 16:119
- (Мұхаммед ﷺ) Раббыңның жолына (Исламға) даналықпен және көркем үгітпен шақыр, және олармен ең көркем түрде тартыс. Басқаларды Аллаһтың жолына шақыру даналықпен және мейірімділікпен болуы керек. 16:125
- Аллаһ тақуалармен (Оған деген міндеттерін орындаушылармен) және ізгілермен бірге. 16:128
- Бұл Құран ең тура және әділ нәрсеге жол көрсетеді. 17:9
- Ешкім басқа біреудің күнәсін көтермейді. 17:15
- Кім ақыретті қаласа және ол үшін соған лайықты түрде тырысса, әрі ол мүмін болса, онда осындайлардың тырысуы бағаланып, сыйға ие болады (Аллаһ тарапынан). 17:19
- Ата-аналарыңды құрметтеңдер және оларға мейірімділікпен қараңдар. Ата-анаға бағынышты болыңдар. Оларға құрметсіз сөз айтпаңдар. Раббың сендерге Одан басқа ешкімге құлшылық етпеуді бұйырды. Және ата-анаға жақсылық жасауды. Егер олардың біреуі немесе екеуі де сенің қасыңда кәрілікке жетсе, оларға "уф" демеңдер және оларға айқайламаңдар, керісінше, оларға құрметті сөз айтыңдар. 17:23
- Оларға кішіпейілділік пен мейірім қанатын жаю және айт: "Раббым! Олар маған кішкентай кезімде қамқорлық жасағандай, Сен де оларға рахым ет." 17:24
- Ысырапшылар шайтандардың бауырлары, ал шайтан Раббысына шүкіршіліксіз. 17:27
- Ақшаны ысырап етпеңдер. 17:29
- Кедейліктен қорыққаннан балаларыңды өлтірмеңдер. 17:31
- Зинаға жақындамаңдар. Некенің киелілігін сақтаңдар және зинадан аулақ болыңдар. 17:32
- Өлшегенде толық өлшеңдер және тура таразымен тартыңдар. Бұл (пайдалы) жақсы және соңы жақсы. 17:35
- (Адам) өзің білмейтін нәрсеге ерме (мысалы, көрмесе де "Мен көрдім" немесе естімесе де "Мен естідім" деп айту). 17:36
- Кішіпейіл болыңдар және тәкаппар болмаңдар. Жер бетінде тәкаппарланып жүрмеңдер. Сен жерді жарып, таулардың биіктігіне жете алмайсың. 17:37
- Раббың сендерді жақсы біледі; егер Ол қаласа, сендерге рахым етеді, немесе егер Ол қаласа, сендерді азаптайды. 17:54
- Кім дүниеде соқыр болса (яғни Аллаһтың белгілерін көрмей, Оған иман келтірмесе), ол ақыретте де соқыр болады және жолдан да адасқан. 17:72
- Белгіленген намаз уақыттарын сақтаңдар. 17:78
- Расында, біз бұл Құранда адамдарға әр түрлі мысалдар түсіндірдік, бірақ адамдардың көпшілігі (ақиқатты) тек қана күпірлікпен қабыл алмайды. 17:89
- Біз бұл Құранда адамдарға әр түрлі мысалдар келтірдік. Бірақ адам барлық нәрседен қызбалы. 18:54
- Олардың жазасы — тозақ; өйткені олар күпірлік етті және Менің аяттарым мен Елшілерімді келеке-мазақ етті. 18:106
- Аллаһтың (ұлықтығына) бала ие болуы лайық емес (бұл христиандардың Аллаһқа қарсы жаласын білдіреді, Иса Аллаһтың ұлы деп). Ол пәк (және олардың серік қосқандарынан жоғары). 19:35
- Адамдарға жұмсақ сөйлеңдер. 20:44
- Ізгі істерде бір-біріңмен жарысыңдар. 21:90
- Бос сөздерден аулақ болыңдар. 23:3
- Ұятты жерлеріңді сақтаңдар. 23:5
- Жүректеріңді күнәға бейімділіктен сақтаңдар. 23:97
- Басқаларды кешіріңдер және олардың қателерін ғапу етіңдер. 24:22
- Басқалардың жеке өмірін, әсіресе өз үйлерінде құрметтеңдер. Көршілердің құқықтарын орындаңдар. 24:27
